def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    my_c = sum(1 for x in me if x == 'C')
    opp_rate = opp_c / n
    my_rate = my_c / n

    recent_len = min(10, n)
    short_len = min(6, n)
    recent_opp_c = sum(1 for x in op[-recent_len:] if x == 'C')
    short_opp_c = sum(1 for x in op[-short_len:] if x == 'C')
    recent_rate = recent_opp_c / recent_len
    short_rate = short_opp_c / short_len

    run_op_d = 0
    for x in reversed(op):
        if x == 'D':
            run_op_d += 1
        else:
            break

    run_opp_c = 0
    for x in reversed(op):
        if x == 'C':
            run_opp_c += 1
        else:
            break

    run_dd = 0
    for h in reversed(history):
        if h[0] == 'D' and h[1] == 'D':
            run_dd += 1
        else:
            break

    run_cd = 0
    for h in reversed(history):
        if h[0] == 'C' and h[1] == 'D':
            run_cd += 1
        else:
            break

    run_cc = 0
    for h in reversed(history):
        if h[0] == 'C' and h[1] == 'C':
            run_cc += 1
        else:
            break

    look = min(12, n)
    cd_recent = sum(1 for h in history[-look:] if h[0] == 'C' and h[1] == 'D')

    prev_c = 0
    after_c = 0
    prev_d = 0
    after_d = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        if pm == 'C':
            prev_c += 1
            if co == 'C':
                after_c += 1
        else:
            prev_d += 1
            if co == 'C':
                after_d += 1

    too_many_failed_probes = (cd_recent >= 5) or (cd_recent >= 4 and run_op_d >= 6)

    hostile = False
    if opp_rate <= 0.30 and recent_rate <= 0.40:
        hostile = True
    elif run_op_d >= 8 and recent_rate <= 0.45:
        hostile = True
    elif cd_recent >= 5 and run_op_d >= 8:
        hostile = True

    evidence_exploit = False
    if not hostile and short_rate >= 0.65 and opp_rate >= 0.55:
        if prev_d >= 1 and after_d * 3 >= prev_d * 2 and run_opp_c >= 3:
            evidence_exploit = True
        elif prev_d >= 3 and after_d >= 2 and run_opp_c >= 5:
            evidence_exploit = True

    last_me = me[-1]
    last_op = op[-1]

    if last_op == 'D':
        if hostile:
            return 'D'

        if run_dd >= 2 and not too_many_failed_probes:
            return 'C'

        if run_cd == 1 and last_me == 'C':
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D' and not too_many_failed_probes:
                return 'C'

            if run_op_d == 1 and (
                recent_rate >= 0.45 or
                opp_rate >= 0.55 or
                short_rate >= 0.5 or
                n < 15
            ):
                return 'C'

        return 'D'

    else:
        if hostile:
            return 'D'

        if evidence_exploit:
            if rng.random() < 0.9:
                return 'D'
            return 'C'

        if last_me == 'D':
            if run_opp_c >= 6 and recent_rate >= 0.85 and rng.random() < 0.25:
                return 'D'
            return 'C'

        if (
            n > 15 and
            n < 90 and
            run_opp_c >= 8 and
            recent_rate >= 0.75 and
            opp_rate >= 0.55
        ):
            if rng.random() < 0.03:
                return 'D'
            return 'C'

        return 'C'
